style.css:
@-moz-document regexp(".*") {
/* Apply the MAXIDENT X to the default arrow cursor */
    html, body, p, div, span, applet, object, iframe, h1, h2, h3, h4, h5, h6, blockquote, pre, a, abbr, acronym, address, big, cite, code, del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, b, u, i, center, dl, dt, dd, ol, ul, li, fieldset, form, label, legend, table, caption, tbody, tfoot, thead, tr, th, td, article, aside, canvas, details, embed, figure, figcaption, footer, header, hgroup, menu, nav, output, ruby, section, summary, time, mark, audio, video {
        cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://w3.org" width="32" height="32" viewBox="0 0 32 32"><path d="M4,4 L12,12 L4,20 M12,12 L20,4 L28,4 M20,4 L20,12 M28,4 L20,4 M12,12 L24,24 L28,20 M24,24 L24,16 M24,24 L16,24" stroke="%23ff66b2" stroke-width="4.5" stroke-linecap="square" stroke-linejoin="miter" fill="none"/></svg>') 12 12, auto !important;
    }

    /* Apply to hoverable/clickable items while keeping pointer usability */
    a, button, input[type="submit"], input[type="button"], input[type="image"], label, select, [role="button"], .pointer {
        cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://w3.org" width="32" height="32" viewBox="0 0 32 32"><path d="M4,4 L12,12 L4,20 M12,12 L20,4 L28,4 M20,4 L20,12 M28,4 L20,4 M12,12 L24,24 L28,20 M24,24 L24,16 M24,24 L16,24" stroke="%23ff1493" stroke-width="4.5" stroke-linecap="square" stroke-linejoin="miter" fill="none"/></svg>') 12 12, pointer !important;
    }
}
